mapper.update:
update
    ssm_dataset_ctg_inherit
set
    is_inherited = #{isInherited},
    updated_time = now(),
    updated_by = #{updatedBy}
where
    item_type = #{itemType}
    and item_value = #{itemValue}

mapper.delete:
delete from
    ssm_dataset_ctg_inherit
where
    item_type = #{itemType}
    and item_value = #{itemValue}

mapper.select:
select
    count(1)
from
    ssm_dataset_ctg_inherit
where item_type = #{itemType}
    and item_value = #{itemValue}
